import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print("check failed:", e)
        sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import json, subprocess, sys
want = {"search the kb for a fact": "kb_search"}
got = {}
for need in want:
    r = subprocess.run([sys.executable, "_tools/kbtools.py", need, "--json"], capture_output=True, text=True)
    es = json.loads(r.stdout)["entries"] if r.returncode == 0 else []
    got[need] = es[0]["tool"] if es else None
assert got == want, ("a need no longer ranks the tool that answers it first", got, want)
